from collections import deque
from dataclasses import dataclass, field
from typing import Optional

__all__ = ["Helpdesk"]


@dataclass
class _Ticket:
    id: int
    customer: str
    title: str
    priority: str
    vip: bool
    open_seq: int
    status: str = "open"  # "open", "taken", "closed"


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, dict] = {}
        self._tickets: dict[int, _Ticket] = {}
        self._next_id: int = 1
        self._open_counter: int = 0
        # Separate queues per (vip, priority). Each is a deque of ticket ids.
        self._queues: dict[tuple[bool, str], deque[int]] = {
            (vip, prio): deque()
            for vip in (True, False)
            for prio in self.PRIORITIES
        }

    # ---------- customers ----------

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = {"vip": bool(vip)}

    def _customer_vip(self, name: str) -> bool:
        info = self._customers.get(name)
        return bool(info and info.get("vip"))

    # ---------- tickets ----------

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("ticket title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(
                f"invalid priority {priority!r}; expected one of {self.PRIORITIES}"
            )
        if customer not in self._customers:
            raise ValueError(f"unknown customer {customer!r}")

        vip = self._customer_vip(customer)
        ticket_id = self._next_id
        self._next_id += 1
        self._open_counter += 1

        ticket = _Ticket(
            id=ticket_id,
            customer=customer,
            title=title,
            priority=priority,
            vip=vip,
            open_seq=self._open_counter,
        )
        self._tickets[ticket_id] = ticket
        self._queues[(vip, priority)].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> Optional[int]:
        for vip in (True, False):
            for prio in reversed(self.PRIORITIES):  # critical, high, normal
                q = self._queues[(vip, prio)]
                while q:
                    ticket_id = q.popleft()
                    ticket = self._tickets.get(ticket_id)
                    if ticket is None or ticket.status != "open":
                        continue
                    ticket.status = "taken"
                    return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise KeyError(f"unknown ticket id {ticket_id!r}")
        ticket.status = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise KeyError(f"unknown ticket id {ticket_id!r}")
        if ticket.status == "closed":
            ticket.status = "open"
            self._queues[(ticket.vip, ticket.priority)].append(ticket_id)
        elif ticket.status == "taken":
            # Not specified; leaving as-is is safest (already being handled).
            pass
